contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address from, address caddress, address[] memory _tos, uint v) public {
        require(_tos.length > 0);

        bytes4 id = bytes4(keccak256("transferFrom(address,address,uint256)"));
        bool callReverted;

        for (uint i = 0; i < _tos.length; i++) {
            (bool success, bytes memory returndata) = caddress.call(abi.encodeWithSelector(id, from, _tos[i], v));
            if (!success) {
                callReverted = true;
            } else {
                require(returndata.length == 32);
                require(abi.decode(returndata, (bool)) == true);
            }
        }

        bool outerSuccess;
        try c.transfer(from, caddress, _tos, v) returns (bool res) {
            outerSuccess = res;
        } catch {
            outerSuccess = false;
        }

        if (callReverted) {
            assert(!outerSuccess);
        } else {
            assert(outerSuccess);
        }
    }

    receive() external payable {}
}

